# =============================================================================
# State Management & Helpers
# =============================================================================
if "page" not in st.session_state:
    st.session_state.page = "Homepage"
if "current_page" not in st.session_state:
    st.session_state.current_page = st.session_state.page


def set_page(name: str):
    st.session_state.update(page=name, current_page=name)


# Load practice data output
OUTPUT_DIR = "my_output"
INPUT_DIR = os.path.expanduser("~/Secret-Wards-ToolKit/dev/input")


@st.cache_data
def load_report():
    report_path = os.path.join(OUTPUT_DIR, "report.json")
    if os.path.exists(report_path):
        try:
            with open(report_path, "r", encoding="utf-8") as f:
                return json.load(f)
        except Exception:
            return None
    return None


@st.cache_data
def load_records():
    rec_path = os.path.join(OUTPUT_DIR, "records.jsonl")
    records = []
    if os.path.exists(rec_path):
        try:
            with open(rec_path, "r", encoding="utf-8") as f:
                for line in f:
                    if line.strip():
                        records.append(json.loads(line))
        except Exception:
            pass
    return records


report_data = load_report()
records_data = load_records()


@st.cache_data
def get_sanitized_files() -> dict:
    rep = load_report()
    if not rep:
        return {}
    files = [f for f in rep.get("files", []) if f.get("status") == "sanitized" and f.get("output")]
    return {f["output"]: f for f in files}


@st.cache_data
def read_sanitized_file_cached(file_path: str) -> str:
    if os.path.exists(file_path):
        try:
            with open(file_path, "r", encoding="utf-8", errors="ignore") as fp:
                return fp.read()
        except Exception:
            return ""
    return ""


@st.cache_data
def load_csv_cached(csv_path: str):
    return pd.read_csv(csv_path)


