def get_bg_toggle_css(active_page: str) -> str:
    common_css = """
    .stApp {
        background-color: #060A12 !important;
        background: #060A12 !important;
        color: #E2E8F0 !important;
    }
    div[data-testid="stElementContainer"]:has(#persistent-bg-container) {
        position: absolute !important;
        height: 0px !important;
        width: 0px !important;
        overflow: visible !important;
        margin: 0 !important;
        padding: 0 !important;
        border: none !important;
        pointer-events: none !important;
    }
    [data-stale="true"] { opacity: 1 !important; transition: none !important; }
    [data-testid="stStatusWidget"] { display: none !important; }
    """
    if active_page == "Homepage":
        return clean_html(
            f"""
            <style>
            {common_css}
            .bg-layer-home {{ opacity: 1 !important; visibility: visible !important; }}
            .bg-layer-arch {{ opacity: 0 !important; visibility: hidden !important; }}
            .bg-layer-sand {{ opacity: 0 !important; visibility: hidden !important; }}
            </style>
            """
        )
    elif active_page == "Architecture":
        return clean_html(
            f"""
            <style>
            {common_css}
            .bg-layer-home {{ opacity: 0 !important; visibility: hidden !important; }}
            .bg-layer-arch {{ opacity: 1 !important; visibility: visible !important; }}
            .bg-layer-sand {{ opacity: 0 !important; visibility: hidden !important; }}
            </style>
            """
        )
    else:  # Live Sandbox
        return clean_html(
            f"""
            <style>
            {common_css}
            .bg-layer-home {{ opacity: 0 !important; visibility: hidden !important; }}
            .bg-layer-arch {{ opacity: 0 !important; visibility: hidden !important; }}
            .bg-layer-sand {{ opacity: 1 !important; visibility: visible !important; }}
            </style>
            """
        )


# =============================================================================
# Main Router
# =============================================================================
def main():
    # Sidebar quick navigation and system scorecard
    st.sidebar.markdown("### 🏛️ DEVFORGE SECRET WARDS")
    st.sidebar.markdown("**Team:** `devforge-secret-wards`")
    st.sidebar.markdown("**Repository:** ")
    st.sidebar.markdown("---")

    page_options = ["Homepage", "Architecture", "Live Sandbox"]
    curr_page = st.session_state.get("page") or st.session_state.get("current_page", "Homepage")
    if curr_page not in page_options:
        curr_page = "Homepage"
    st.session_state.page = curr_page
    st.session_state.current_page = curr_page

    curr_idx = page_options.index(curr_page)
    sb_page = st.sidebar.radio(
        "Navigation",
        page_options,
        index=curr_idx,
        key=f"nav_radio_{curr_page.replace(' ', '_')}",
    )
    if sb_page != curr_page:
        set_page(sb_page)
        st.rerun()

    st.sidebar.markdown("---")
    st.sidebar.markdown("### 📊 Benchmark Metrics")
    st.sidebar.markdown(
        """
        - **PII Leaked:** `0.0%` (0 / 3,230)
        - **Medical Kept:** `100.0%` (4,855 / 4,855)
        - **Canary Leaks:** `0 / 4`
        - **Linking F0.5:** `0.99`
        - **Runtime:** `0.76s` CPU
        - **RAM:** `44.5 MB` peak
        - **Contract:** `CONTRACT OK`
        """
    )

    # Route Page
    active_page = st.session_state.get("page") or st.session_state.get("current_page", "Homepage")

    # Persistent edge-to-edge background GIF layers mounted outside conditionals (0 bytes re-sent on tab switch)
    st.markdown(get_persistent_bg_html(), unsafe_allow_html=True)
    st.markdown(get_bg_toggle_css(active_page), unsafe_allow_html=True)

    if active_page == "Homepage":
        render_homepage()
    elif active_page == "Architecture":
        render_architecture()
    elif active_page == "Live Sandbox":
        render_live_sandbox()
    else:
        render_homepage()


if __name__ == "__main__":
    main()
